import { GetSecretValueCommand, SecretsManagerClient } from '@aws-sdk/client-secrets-manager';

let loaded = false;

/**
 * In AWS, credentials live in Secrets Manager. At cold start we read them once and
 * populate process.env so the rest of the code works the same locally and in Lambda.
 *
 * - DB_SECRET_ARN: secret generated by RDS ({ username, password, host, port, dbname })
 * - APP_SECRET_ARN: JSON with JWT_SECRET, WHATSAPP_*, MERCADOPAGO_* keys
 */
export async function loadSecrets(): Promise<void> {
  if (loaded) return;
  const client = new SecretsManagerClient({});
  const get = async (arn: string) => {
    const res = await client.send(new GetSecretValueCommand({ SecretId: arn }));
    return JSON.parse(res.SecretString ?? '{}') as Record<string, string | number>;
  };

  if (process.env.DB_SECRET_ARN && !process.env.DATABASE_URL) {
    const s = await get(process.env.DB_SECRET_ARN);
    const user = encodeURIComponent(String(s.username));
    const pass = encodeURIComponent(String(s.password));
    process.env.DATABASE_URL = `postgres://${user}:${pass}@${s.host}:${s.port}/${s.dbname ?? 'agenda'}`;
    process.env.DB_SSL ??= 'true';
  }
  if (process.env.APP_SECRET_ARN) {
    const s = await get(process.env.APP_SECRET_ARN);
    for (const [k, v] of Object.entries(s)) {
      if (v !== '' && process.env[k] === undefined) process.env[k] = String(v);
    }
  }
  loaded = true;
}
